// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.decisionimport com.roshan.persona.cognitive.model.DecisionCriterionimport com.roshan.persona.cognitive.model.DecisionOptionimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Criteria Analyzer (Module 7 v2 — Step 7.5). * * Extracts decision criteria from user input and scores each option against * those criteria. * * ## What it does * * 1. **Extract criteria** — "iPhone vs Android" → [price, camera, battery, *    ecosystem, customization]. Uses heuristics for common decision types *    + LLM for novel ones (v1: heuristics only). * 2. **Score options** — given criteria + options, assign 0.0–1.0 score per *    criterion per option. Uses LLM (v1: returns placeholder scores; real *    impl wires to Module 4). * * ## Heuristic criteria extraction * * Common decision types have known criteria: *  - Phone comparison → price, camera, battery, ecosystem, customization *  - Car comparison → price, fuel efficiency, reliability, safety, features *  - Travel options → cost, time, comfort, convenience *  - Investment → return, risk, liquidity, tax * * For unknown types, returns generic criteria: [price, quality, convenience]. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§DecisionMaker</a> */class CriteriaAnalyzer(    private val dispatcher: CoroutineDispatcher,) {    /**     * Extract decision criteria from [query].     *     * @param query the user's decision query ("iPhone vs Android").     * @return list of criteria with default weights.     */    suspend fun extractCriteria(query: String): List<DecisionCriterion> = withContext(dispatcher) {        val lower = query.lowercase()        // Phone comparison.        if (PHONE_KEYWORDS.any { lower.contains(it) }) {            return@withContext PHONE_CRITERIA        }        // Car comparison.        if (CAR_KEYWORDS.any { lower.contains(it) }) {            return@withContext CAR_CRITERIA        }        // Travel options.        if (TRAVEL_KEYWORDS.any { lower.contains(it) }) {            return@withContext TRAVEL_CRITERIA        }        // Investment.        if (INVESTMENT_KEYWORDS.any { lower.contains(it) }) {            return@withContext INVESTMENT_CRITERIA        }        // Generic fallback.        GENERIC_CRITERIA    }    /**     * Score each [option] against each [criterion] using real heuristic scoring.     *     * Returns a map of option name → (criterion name → score 0.0–1.0).     *     * ## v1 Heuristic Approach (per strategy v2 §"CriteriaAnalyzer")     *     * We extract numeric signals from each option's name + description and     * compare across options. Lower-is-better criteria (cost, time, risk) are     * inverted so that the smallest value gets the highest score. The LLM     * upgrade path (v2) will replace this with semantic scoring via Module 4.     *     * ### Recognized criteria (case-insensitive substring match)     *     *  - `cost` / `price` — lower cost wins (extracts currency + magnitude).     *  - `time` / `speed` / `fuel_efficiency` — lower duration / higher speed wins.     *  - `quality` / `camera` / `reliability` / `safety` / `rating` /     *    `battery` — higher extracted numeric value wins.     *  - `convenience` — fewer steps / shorter distance wins.     *  - Anything else → neutral 0.5 (no signal available without LLM).     *     * When no numeric signal can be extracted from any option for a given     * criterion, all options receive a neutral 0.5 score for that criterion     * (so the [DecisionMaker]'s overall weighted sum isn't biased).     *     * @param options the options to score (e.g., ["iPhone 15 ($999)", "Pixel 8 ($699)"]).     * @param criteria the criteria to score against.     * @return map of option name → (criterion → score in [0.0, 1.0]).     */    suspend fun scoreOptions(        options: List<String>,        criteria: List<DecisionCriterion>,    ): Map<String, Map<String, Float>> = withContext(dispatcher) {        if (options.isEmpty()) return@withContext emptyMap()        options.associateWith { option ->            criteria.associate { criterion ->                criterion.name to scoreOptionForCriterion(option, criterion.name, options)            }        }    }    /**     * Score a single option for a single criterion by comparing its extracted     * numeric signal against all other options' signals for the same criterion.     *     * Returns a score in `[0.0, 1.0]` where 1.0 = best for this criterion.     * If no signal can be extracted from any option, returns 0.5 (neutral).     */    private fun scoreOptionForCriterion(        option: String,        criterionName: String,        allOptions: List<String>,    ): Float {        val normalized = criterionName.lowercase().replace("_", " ")        val isLowerBetter = isLowerBetterCriterion(normalized)        // Extract numeric signal from each option for this criterion.        val signals = allOptions.associateWith { extractSignal(it, normalized) }        val optionSignal = signals[option] ?: return 0.5f        // If this option has no signal but others do, give it a slight penalty        // (so options with explicit data win over vague ones).        val otherSignals = signals.values.filterNotNull().filter { it != optionSignal }        if (otherSignals.isEmpty()) {            // No option has a signal for this criterion — neutral 0.5 across the board.            return 0.5f        }        // Compute min/max across all extracted signals (including this option's).        val allValues = (otherSignals + optionSignal)        val minValue = allValues.min()        val maxValue = allValues.max()        if (maxValue == minValue) return 0.5f  // All same — neutral.        // Normalize this option's signal to [0,1].        val normalizedScore = (optionSignal - minValue) / (maxValue - minValue)        val finalScore = if (isLowerBetter) 1.0f - normalizedScore else normalizedScore        return finalScore.coerceIn(0.0f, 1.0f)    }    /**     * Determine whether a criterion is "lower is better" (e.g., cost, time, risk)     * or "higher is better" (e.g., quality, rating, battery).     */    private fun isLowerBetterCriterion(criterionName: String): Boolean {        val lowerBetterKeywords = listOf(            "cost", "price", "time", "duration", "risk", "minimum",            "latency", "delay", "wait", "distance", "steps",        )        return lowerBetterKeywords.any { criterionName.contains(it) }    }    /**     * Extract a numeric signal for [criterionName] from [option].     *     * Strategy:     *  - If the criterion is `cost`/`price`, look for a currency-prefixed     *    number (e.g., "$999", "₹15000", "USD 5.99") — return the numeric     *    magnitude (currency symbols are stripped, units normalized to whole     *    units so $9.99 → 9.99, ₹15000 → 15000).     *  - If the criterion is `time`/`duration`/`speed`, look for a duration     *    pattern (`5h`, `30min`, `2 hours`, `45 minutes`) — return value in     *    minutes for time/duration, or in km/h for speed.     *  - If the criterion is `quality`/`camera`/`rating`/`battery`/`reliability`,     *    look for a 1-10 or 1-100 rating, a megapixel count, a milliamp-hour     *    count, or a percentage — return the numeric magnitude.     *  - Otherwise, look for any digit sequence in the option text.     *     * Returns null if no numeric signal can be extracted.     */    private fun extractSignal(option: String, criterionName: String): Float? {        val text = option.lowercase()        // Cost / price — currency prefix or suffix.        if (criterionName.contains("cost") || criterionName.contains("price")) {            val costRegex = Regex("(?:usd|\\\$|₹|€|£|inr|rs\\.?)\\s*([\\d,]+(?:\\.\\d+)?)")            costRegex.find(text)?.let {                return it.groupValues[1].replace(",", "").toFloatOrNull()            }            // "for 999" / "priced at 999"            val pricedRegex = Regex("(?:priced at|costs?|for|@)\\s*([\\d,]+(?:\\.\\d+)?)")            pricedRegex.find(text)?.let {                return it.groupValues[1].replace(",", "").toFloatOrNull()            }        }        // Time / duration / speed — convert to a single comparable unit.        if (criterionName.contains("time") || criterionName.contains("duration") ||            criterionName.contains("speed") || criterionName.contains("fuel")        ) {            // Hours + minutes → minutes.            val hoursMinsRegex = Regex(                "(\\d+)\\s*(?:h|hr|hrs|hour|hours)\\s*(?:and\\s*)?(\\d+)?\\s*(?:m|min|mins|minute|minutes)?",            )            hoursMinsRegex.find(text)?.let { match ->                val hours = match.groupValues[1].toIntOrNull() ?: 0                val minutes = match.groupValues[2].toIntOrNull() ?: 0                return (hours * 60 + minutes).toFloat()            }            // Just minutes.            val minsRegex = Regex("(\\d+)\\s*(?:m|min|mins|minute|minutes)")            minsRegex.find(text)?.let {                return it.groupValues[1].toFloatOrNull()            }            // Just hours.            val hoursRegex = Regex("(\\d+)\\s*(?:h|hr|hrs|hour|hours)")            hoursRegex.find(text)?.let {                val hours = it.groupValues[1].toFloatOrNull() ?: return@let null                return hours * 60f            }            // Fuel efficiency (kmpl / mpg) — higher is better → return as-is.            val kmplRegex = Regex("(\\d+(?:\\.\\d+)?)\\s*(?:kmpl|km/l|mpg)")            kmplRegex.find(text)?.let {                return it.groupValues[1].toFloatOrNull()            }        }        // Quality / camera / battery / reliability / rating — higher is better.        if (criterionName.contains("quality") || criterionName.contains("camera") ||            criterionName.contains("battery") || criterionName.contains("reliability") ||            criterionName.contains("safety") || criterionName.contains("rating") ||            criterionName.contains("return") || criterionName.contains("features") ||            criterionName.contains("ecosystem") || criterionName.contains("customization") ||            criterionName.contains("comfort") || criterionName.contains("convenience") ||            criterionName.contains("liquidity") || criterionName.contains("tax")        ) {            // Megapixels (camera).            val mpRegex = Regex("(\\d+(?:\\.\\d+)?)\\s*mp(?:\\s|\\b)")            mpRegex.find(text)?.let {                if (criterionName.contains("camera")) {                    return it.groupValues[1].toFloatOrNull()                }            }            // Battery mAh.            val mahRegex = Regex("(\\d+)\\s*mah")            mahRegex.find(text)?.let {                if (criterionName.contains("battery")) {                    return it.groupValues[1].toFloatOrNull()                }            }            // Star rating (e.g., "4.5 stars", "rated 4.5").            val ratingRegex = Regex("(?:rated?\\s*)?(\\d(?:\\.\\d)?)\\s*(?:stars?|/\\s*5|/5)")            ratingRegex.find(text)?.let {                return it.groupValues[1].toFloatOrNull()            }            // Percentage.            val percentRegex = Regex("(\\d+(?:\\.\\d+)?)\\s*%")            percentRegex.find(text)?.let {                return it.groupValues[1].toFloatOrNull()            }            // Generic 1-10 / 1-100 rating suffix.            val genericRatingRegex = Regex("\\b(\\d{1,3})(?:\\.\\d)?\\s*/\\s*(10|100)\\b")            genericRatingRegex.find(text)?.let {                val value = it.groupValues[1].toFloatOrNull() ?: return@let null                val scale = it.groupValues[2].toFloatOrNull() ?: return@let null                return if (scale > 0) (value / scale) * 100f else null            }        }        // Fallback: any standalone number in the option text.        val anyNumberRegex = Regex("\\b(\\d+(?:\\.\\d+)?)\\b")        return anyNumberRegex.find(text)?.groupValues?.getOrNull(1)?.toFloatOrNull()    }    /**     * Calculate the overall score for an option given weighted criteria.     *     * @param scores criterion → score (0.0–1.0).     * @param criteria the criteria with weights.     * @return weighted average (0.0–1.0).     */    fun calculateOverallScore(        scores: Map<String, Float>,        criteria: List<DecisionCriterion>,    ): Float {        if (scores.isEmpty() || criteria.isEmpty()) return 0f        val totalWeight = criteria.sumOf { it.weight.toDouble() }.toFloat()        if (totalWeight == 0f) return 0f        val weightedSum = criteria.sumOf { criterion ->            ((scores[criterion.name] ?: 0f) * criterion.weight).toDouble()        }.toFloat()        return (weightedSum / totalWeight).coerceIn(0f, 1f)    }    // ─── Heuristic criteria sets ───────────────────────────────────────────    companion object {        private val PHONE_KEYWORDS = listOf("phone", "iphone", "android", "samsung", "smartphone")        private val CAR_KEYWORDS = listOf("car", "vehicle", "sedan", "suv", "hatchback")        private val TRAVEL_KEYWORDS = listOf("flight", "train", "bus", "trip", "travel", "vacation")        private val INVESTMENT_KEYWORDS = listOf("invest", "stock", "mutual fund", "fd", "crypto")        val PHONE_CRITERIA = listOf(            DecisionCriterion("price", 0.3f, "Cost of the device"),            DecisionCriterion("camera", 0.2f, "Camera quality"),            DecisionCriterion("battery", 0.2f, "Battery life"),            DecisionCriterion("ecosystem", 0.15f, "App ecosystem and integration"),            DecisionCriterion("customization", 0.15f, "Customization and flexibility"),        )        val CAR_CRITERIA = listOf(            DecisionCriterion("price", 0.3f, "Purchase price"),            DecisionCriterion("fuel_efficiency", 0.2f, "Fuel economy"),            DecisionCriterion("reliability", 0.2f, "Long-term reliability"),            DecisionCriterion("safety", 0.2f, "Safety features and ratings"),            DecisionCriterion("features", 0.1f, "Features and technology"),        )        val TRAVEL_CRITERIA = listOf(            DecisionCriterion("cost", 0.35f, "Total cost"),            DecisionCriterion("time", 0.25f, "Travel time"),            DecisionCriterion("comfort", 0.2f, "Comfort level"),            DecisionCriterion("convenience", 0.2f, "Booking and schedule convenience"),        )        val INVESTMENT_CRITERIA = listOf(            DecisionCriterion("return", 0.3f, "Expected return rate"),            DecisionCriterion("risk", 0.25f, "Risk level"),            DecisionCriterion("liquidity", 0.2f, "How easily you can withdraw"),            DecisionCriterion("tax", 0.15f, "Tax implications"),            DecisionCriterion("minimum", 0.1f, "Minimum investment amount"),        )        val GENERIC_CRITERIA = listOf(            DecisionCriterion("price", 0.35f, "Cost"),            DecisionCriterion("quality", 0.35f, "Quality"),            DecisionCriterion("convenience", 0.3f, "Convenience"),        )    }}

